CREATE TABLE vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, registration_number VARCHAR(50) NOT NULL, vehicle_type ENUM('car','taxi','bus','truck','motorcycle','van','other') NOT NULL, brand VARCHAR(100) NOT NULL, model VARCHAR(100) NULL, manufacture_year SMALLINT UNSIGNED NULL, capacity DECIMAL(15,2) NULL, status ENUM('available','assigned','maintenance','inactive','retired') NOT NULL DEFAULT 'available', acquisition_date DATE NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_vehicles_registration (registration_number), KEY idx_vehicles_type_status (vehicle_type,status), CONSTRAINT chk_vehicle_year CHECK (manufacture_year IS NULL OR manufacture_year BETWEEN 1900 AND 2200), CONSTRAINT chk_vehicle_capacity CHECK (capacity IS NULL OR capacity >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
